<?php $rows=db()->query('SELECT u.id,u.username,u.email,u.is_active,r.role_name,p.full_name,p.designation FROM users u LEFT JOIN roles r ON r.id=u.role_id LEFT JOIN user_profiles p ON p.user_id=u.id ORDER BY u.id')->fetchAll(); ?>
<div class="card p-3"><h5>User Management</h5><table class="table table-sm"><tr><th>User</th><th>Name</th><th>Designation</th><th>Email</th><th>Role</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['designation'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role_name'])?></td><td><?= $r['is_active']?'Active':'Inactive' ?></td></tr><?php endforeach;?></table></div>
